);
$st = $conn->prepare(
    "INSERT INTO `gov_screen_cycle`
        (`company_id`,`dept_name`,`layer_name`,`stage_order`,`stage_name`,`group_name`,
         `screen_title`,`screen_file`,`inputs_note`,`output_doc`,`resp_role`,`next_state`,`consumers`,`fin_impact`)
     VALUES (0,?,?,?,?,?,?,?,?,?,?,?,?,?)");
$n = 0;
foreach ($SHEET as $r) {
    $st->bind_param('sssssssssssss',
        $r[0], $r[1], $r[2], $r[3], $r[4], $r[5], $r[6], $r[7], $r[8], $r[9], $r[10], $r[11], $r[12]);
    if ($st->execute()) { $n++; } else { echo "   ✗ {$r[5]}: {$st->error}\n"; }
}
$st->close();
printf("✔ صفوفٌ مبذورةٌ حرفًا: %d من 663\n", $n);
